package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.mozilla.testing.BaseTestUtil;
import com.google.javascript.jscomp.mozilla.testing.NodeTraversal;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.mozilla.testing.BaseTestUtil.createNode;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_visit_TriageGen0Test {

  private CheckGlobalThis checkGlobalThis;

  @Mock private NodeTraversal mockTraversal;
  @Mock private Compiler mockCompiler;
  @Mock private ErrorReporter mockErrorReporter;

  @Before
  public void setUp() {
    MockitoAnnotations.initMocks(this);
    checkGlobalThis = new CheckGlobalThis(mockCompiler);
    // Note: Since level and GLOBAL_THIS are likely internal constants/fields, 
    // we assume the environment allows the compiler to handle the error reporting structure.
  }

  @Test
  public void testVisit_NoThisNoAssignLhs() {
    Node n = createNode(Token.NAME, "x");
    Node parent = createNode(Token.VAR);

    checkGlobalThis.visit(mockTraversal, n, parent);

    verify(mockCompiler, never()).report(any());
  }

  @Test
  public void testVisit_IsThisButShouldNotReport() {
    Node n = createNode(Token.THIS);
    Node parent = createNode(Token.EXPRESSION);

    // We need to mock shouldReportThis. Since it's part of the same class, 
    // in a real scenario we'd use a spy or ensure the logic of shouldReportThis returns false.
    // For this test, we assume the internal state of CheckGlobalThis makes shouldReportThis return false.
    CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
    when(spyCheck.shouldReportThis(n, parent)).thenReturn(false);

    spyCheck.visit(mockTraversal, n, parent);

    verify(mockCompiler, never()).report(any());
  }

  @Test
  public void testVisit_IsThisAndShouldReport() {
    Node n = createNode(Token.THIS);
    Node parent = createNode(Token.EXPRESSION);

    // Mocking the error creation flow
    // t.makeError returns a Job/Error object
    // Since we don't have the exact type of the return of makeError, we use any()

    CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
    when(spyCheck.shouldReportThis(n, parent)).thenReturn(true);
    when(mockTraversal.makeError(any(), any(), any())).thenReturn(null); 

    spyCheck.visit(mockTraversal, n, parent);

    verify(mockCompiler).report(any());
  }

  @Test
  public void testVisit_IsAssignLhsChild() {
    Node n = createNode(Token.NAME, "target");
    Node parent = createNode(Token.ASSIGN);

    // Set the internal field via reflection if it's private, 
    // but assuming for this test we can trigger the branch logic.
    // Since we cannot access private field 'assignLhsChild' directly, 
    // we assume the test environment allows setting it or it's set by previous logic.

    // We simulate the state where n == assignLhsChild
    setAssignLhsChild(n);

    checkGlobalThis.visit(mockTraversal, n, parent);

    // If the branch is hit, assignLhsChild should become null.
    // We verify by checking if a subsequent visit with the same node doesn't trigger anything 
    // (though the code doesn't have a branch for that, the side effect is the nulling).
    assertAssignLhsChildIsNull();
  }

  @Test
  public void testVisit_IsThisAndIsAssignLhsChild() {
    Node n = createNode(Token.THIS);
    Node parent = createNode(Token.EXPRESSION);

    CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
    when(spyCheck.shouldReportThis(n, parent)).thenReturn(true);
    when(mockTraversal.makeError(any(), any(), any())).thenReturn(null);

    setAssignLhsChild(n);

    spyCheck.visit(mockTraversal, n, parent);

    verify(mockCompiler).report(any());
    assertAssignLhsChildIsNull();
  }

  // Helper methods to simulate access to private fields for testing purposes
  private void setAssignLhsChild(Node n) {
    try {
      java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
      field.setAccessible(true);
      field.set(checkGlobalThis, n);
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }

  private void assertAssignLhsChildIsNull() {
    try {
      java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
      field.setAccessible(true);
      assert field.get(checkGlobalThis) == null;
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }
}
